    );

    // mv a file onto itself is a no-op
    let moved = fs.resolve(incoming, "source.txt").unwrap();
    fs.move_file_path(ROOT_NODE, "/incoming/source.txt", "/incoming/source.txt")
        .unwrap();
    assert_eq!(fs.kind(moved), Ok(EntryKind::File));
}

